// Loads src/data/dataset.json (generated by build_dataset.py from the curated
// workbook) and joins each result to its cohort and publication.
import raw from "./dataset.json";
import type { Cohort, Column, EvidenceRecord, Publication, Result } from "./types";

interface Table<T> { sheet: string; columns: Column[]; rows: T[] }
interface Dataset {
  source: { file: string; sha256: string; version: string | null; savedDate: string | null };
  publications: Table<Publication>;
  cohorts: Table<Cohort>;
  results: Table<Result>;
  cohortAliases?: { alias: string; canonical: string; conflicts: { field: string; alias: unknown; canonical: unknown }[] }[];
}

const data = raw as unknown as Dataset;

export const SOURCE = data.source;
export const PUBLICATION_COLUMNS = data.publications.columns;
export const COHORT_COLUMNS = data.cohorts.columns;
export const RESULT_COLUMNS = data.results.columns;

export const PUBLICATIONS = data.publications.rows;
/** Every 2.Cohort row, exactly as in the workbook (including documented alias rows). */
export const COHORT_ROWS = data.cohorts.rows;
/** Unique cohorts for counting and aggregation: a documented alias row is counted under its canonical cohort. */
export const COHORTS = COHORT_ROWS.filter((c) => !c.aliasOf);
/** Documented cohort aliases and any fields that differ between the two rows (flagged for the curators). */
export const COHORT_ALIASES = data.cohortAliases ?? [];
export const RESULTS = data.results.rows;

export const PUBLICATION_BY_ID = new Map(PUBLICATIONS.map((p) => [p.id, p]));
export const COHORT_BY_ID = new Map(COHORT_ROWS.map((c) => [c.id, c]));

/** Display label for a column, e.g. "SEX – Female" or "Number". */
export function columnLabel(c: Column): string {
  return c.sub ? `${c.label} – ${c.sub}` : c.label;
}

/** Number of publications reporting each miRNA (used for the calculated "replicated" flag). */
const studiesPerMirna = new Map<string, Set<string>>();
RESULTS.forEach((r) => {
  if (!studiesPerMirna.has(r.microRNA)) studiesPerMirna.set(r.microRNA, new Set());
  studiesPerMirna.get(r.microRNA)!.add(r.publicationId);
});

export const EVIDENCE: EvidenceRecord[] = RESULTS.map((r) => {
  const publication = PUBLICATION_BY_ID.get(r.publicationId)!;
  return {
    id: r.id,
    result: r,
    cohort: r.cohortId ? COHORT_BY_ID.get(r.cohortId)! : null,
    publication,
    mirna: r.microRNA,
    direction: r.direction,
    biospecimen: r.tissue,
    biospecimenKey: r.tissue.trim(),
    studyId: r.publicationId,
    year: Number(publication.year),
    country: publication.location,
    countryIso: publication.countryIso,
    replicated: studiesPerMirna.get(r.microRNA)!.size >= 2,
  };
});
